#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room with date, other day"; fail=1; }
o=$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null); c=$?
[ $c = 2 ] && [ -z "$o" ] || { echo "list --room without value: want exit 2 and no stdout, got $c"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null)" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value: usage"; fail=1; }
o=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>/dev/null); c=$?
[ $c = 2 ] && [ -z "$o" ] || { echo "list bad date: want exit 2 and no stdout, got $c"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1 >/dev/null)" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date: message"; fail=1; }
rm -f "$t"; exit $fail

