arguments.new_string:
room=
if [ "${1:-}" = --room ]; then
  [ $# -ge 2 ] || { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
  room=$2; shift 2
fi
d=${1:-}
if [ -n "$d" ]; then
  [[ $d =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]] || { echo "bad date: $d (expected YYYY-MM-DD)" >&2; exit 2; }
fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="$d" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room with other date"; fail=1; }
rm -f "$t"; exit $fail

