#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
printf 'aoi\t2026-01-02\t10:00\t11:00\tz\n' >> "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 10:00-11:00 aoi z' ] || { echo "list --room with date"; fail=1; }
e=$(mktemp)
out=$(BOOKINGS=$t bash src/list.sh --room 2>"$e"); rc=$?
[ "$rc" = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>"$e"); rc=$?
[ "$rc" = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date format"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026-13-01 2>"$e"); rc=$?
[ "$rc" = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'bad date: 2026-13-01 (expected YYYY-MM-DD)' ] || { echo "list bad month"; fail=1; }
rm -f "$t" "$e"; exit $fail

