[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room with other date"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null); rc=$?
[ $rc = 2 ] && [ -z "$out" ] || { echo "list --room without value"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null)
[ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room usage message"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>/dev/null); rc=$?
[ $rc = 2 ] && [ -z "$out" ] || { echo "list bad date exit"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1 >/dev/null)
[ "$err" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date message"; fail=1; }
rm -f "$t"; exit $fail

